pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz: actor and a block timestamp/number context — keep wide so mutant inputs are included
    function testFuzz_property(address actor, uint256 warpTime, uint256 blockNum) public {
        // Keep actor as non-zero
        vm.assume(actor != address(0));

        // Bound warpTime to reasonable unix range and blockNum to non-negative small range
        warpTime = bound(warpTime, 1, 10**12);
        blockNum = bound(blockNum, 1, 1000000);

        // Precondition: we test the behavior when msg.value == 10 ether
        uint256 pay = 10 ether;

        // Give actor funds and set environment
        vm.deal(actor, pay);
        vm.warp(warpTime);
        vm.roll(uint64(blockNum));

        // Record previous pastBlockTime
        uint256 before = c.pastBlockTime();

        // Make the call as actor sending exactly 10 ether
        vm.prank(actor);
        // low-level call to trigger fallback
        (bool ok, ) = address(c).call{value: pay}("");

        // After the call on the correct contract, when a call with msg.value == 10 ether is sent,
        // fallback must accept and update pastBlockTime to block.timestamp + 1.
        // We capture that single general assertion: the call must succeed and pastBlockTime == warpTime + 1
        // (this will hold for the reference and be violated by the mutant which requires 9 ether)
        assertTrue(ok && c.pastBlockTime() == warpTime + 1);
    }
