pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: caller address and a timestamp to warp to
    function testFuzz_property(address caller, uint256 ts) public {
        // keep caller non-zero and distinct from this contract
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));

        // bound timestamp to reasonable future range to avoid overflow issues
        ts = bound(ts, 0, type(uint64).max);

        // initialize pastBlockTime to a known value by making a successful call with higher timestamp
        // pick an initial timestamp greater than 1 to set pastBlockTime = ts_init + 1
        uint256 ts_init = block.timestamp + 100;
        vm.warp(ts_init);
        vm.deal(caller, 20 ether);
        vm.prank(caller);
        // this call should succeed (msg.value == 10 ether)
        c.f{value: 10 ether}();

        // read stored pastBlockTime after the successful initialization
        uint256 stored = c.pastBlockTime();

        // Now warp to the fuzzed timestamp and attempt the call with exactly 10 ether from caller
        vm.warp(ts);
        vm.deal(caller, 20 ether);
        bool ok;
        vm.prank(caller);
        try c.f{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference contract enforces require(block.timestamp > pastBlockTime), so if ts <= stored,
        // the call must revert (ok == false). This is the single assertion reading c's public getter/behavior.
        if (ts <= stored) {
            assertTrue(!ok);
        } else {
            // if ts > stored the call should succeed
            assertTrue(ok);
        }
    }
}

