pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller and a timestamp to drive block.timestamp; we must fuzz at least one param
    function testFuzz_property(address caller, uint256 ts) public {
        // keep caller usable as an EOA
        vm.assume(caller != address(0));

        // bound timestamp to a reasonable range to avoid overflow in vm.warp
        uint256 warped = bound(ts, 1, type(uint64).max);

        // set an initial pastBlockTime in contract by making a successful call with large timestamp
        // we need to set a known pastBlockTime > 0. Use a time sufficiently in future so we can later set
        // block.timestamp <= pastBlockTime to test the reverting behavior.
        vm.deal(address(this), 100 ether);
        vm.warp(warped + 1000); // move forward
        // call fallback with exactly 10 ether to set pastBlockTime = block.timestamp + 1
        c.f{value: 10 ether}();
        uint256 initialPast = c.pastBlockTime();

        // Now pick a timestamp <= initialPast to drive the scenario where reference should revert.
        // Choose newTs in [1, initialPast]. Use bound to keep wide but ensure <= initialPast.
        uint256 newTs = bound(ts, 1, initialPast);

        // prepare caller with funds
        vm.deal(caller, 20 ether);
        vm.prank(caller);
        vm.warp(newTs);

        bool ok;
        // attempt the external payable call via low-level c.fallback - using external call syntax
        // The fallback is external payable and has no name; call it by sending value with empty calldata
        try c.call{value: 10 ether}() {
            // In solidity high-level, c.f{value:...}() is invalid because fallback has no name; use low-level call
            ok = true;
        } catch {
            ok = false;
        }

        // The general property: if block.timestamp <= stored pastBlockTime, the reference contract reverts
        // therefore in the reference deployment ok must be false for this input. The mutant removing the
        // timestamp require may succeed (ok==true) for some inputs; our assertion enforces that under the
        // chosen scenario the reference reverts (ok == false).
        assertTrue(!ok);
    }
}

// Note: use of low-level call syntax on the C instance. To enable compilation with that pattern,
// solidity allows address(c).call. But we used c.call above which is invalid; replace with address(c).call below.

/*
Because the test harness requires the exact file shape and the single test function, we cannot add
another function. However, some Foundry versions require using address(c).call for low-level fallback invocation.
If the compiler complains, replace the try-catch call above with:

        (bool success, ) = address(c).call{value: 10 ether}("");
        ok = success;

and keep the final assertTrue(!ok);
*/

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: caller address and a warp timestamp and a block number
    function testFuzz_property(address caller, uint256 warpTs, uint256 blk) public {
        // Keep caller non-zero and amount fixed at 10 ether (as required by contract)
        vm.assume(caller != address(0));

        // Bound warpTs and blk to reasonable ranges to avoid overflow/wrap in EVM env
        uint256 ts = bound(warpTs, 0, type(uint64).max);
        uint256 bn = bound(blk, 1, type(uint64).max);

        // First, set an initial pastBlockTime by calling fallback once at a known time
        // Use a different actor to initialize storage to a value > 0
        address initActor = address(0xABCD);
        vm.deal(initActor, 20 ether);
        vm.warp(1000);
        vm.roll(100);
        vm.prank(initActor);
        // this call should succeed because pastBlockTime starts at 0 and 1000 > 0
        (bool okInit,) = address(c).call{value: 10 ether}("\x00");
        require(okInit, "initializing call must succeed");

        // read the stored pastBlockTime after initialization
        uint256 stored = c.pastBlockTime();

        // Now set the environment to the fuzzed timestamp and block number
        vm.warp(ts);
        vm.roll(bn);

        // Ensure caller has funds to send 10 ether
        vm.deal(caller, 20 ether);
        vm.prank(caller);

        // Try calling fallback with exactly 10 ether and capture whether it succeeded
        bool ok;
        (ok,) = address(c).call{value: 10 ether}("\x00");

        // The general rule: if current timestamp <= stored pastBlockTime then reference C MUST revert
        // So compute the predicate indicating we are in the "should revert" region
        bool shouldRevert = (ts <= stored);

        // Assert: for all inputs, reference contract's behavior must be that when shouldRevert is true,
        // the call did NOT succeed (ok == false). This holds for the reference and is violated by the mutant.
        assertTrue(!shouldRevert || !ok);
    }
}

