contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the caller address and the block.number parity by fuzzing the block number and timestamp
    function testFuzz_property(address caller, uint64 warpTs, uint64 rollBn) public {
        // admissible domain: caller should not be zero address (keep wide)
        vm.assume(caller != address(0));
        // set timestamp and block number to fuzzed values (keep wide bounds)
        // ensure timestamp > 0
        if(warpTs < 1) warpTs = 1;
        if(rollBn < 1) rollBn = 1;
        vm.warp(uint256(warpTs));
        vm.roll(uint256(rollBn));

        // provide caller with funds and perform the payable fallback with exactly 10 ether
        vm.deal(caller, 20 ether);
        vm.prank(caller);
        c.f{value: 10 ether}();

        // single assertion: after a successful fallback, pastBlockTime (public getter) must be > current block.timestamp
        // This holds for reference (stores block.timestamp + 1) for all inputs, but the mutant that stores block.timestamp
        // will make pastBlockTime == block.timestamp for some inputs and thus violate this assertion.
        assertTrue(c.pastBlockTime() > block.timestamp);
    }
