pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: caller address and a warp time offset to make block.timestamp > pastBlockTime
    function testFuzz_property(address caller, uint256 timeAdvance) public {
        // keep caller non-zero/addressable EOA
        vm.assume(caller != address(0));

        // Ensure timeAdvance is in a reasonable range to avoid overflow and keep wide domain
        timeAdvance = bound(timeAdvance, 1, 1 days);

        // Fund caller so they can send 10 ether
        vm.deal(caller, 20 ether);

        // Ensure initial pastBlockTime is strictly less than current timestamp by warping backwards if needed
        // We'll set pastBlockTime to block.timestamp - 1 by first warping back, then calling with correct timing
        // Warp to a time in the past so block.timestamp > pastBlockTime after we advance
        uint256 start = block.timestamp;
        // Move time forward by timeAdvance so that when we call, block.timestamp will be greater than any prior saved value
        vm.warp(start + timeAdvance);

        // Make the call as caller sending exactly 10 ether
        vm.prank(caller);
        // perform the payable fallback call
        // use low-level call to trigger fallback (no function selector)
        (bool ok, ) = address(c).call{value: 10 ether}("\x00");
        // The call should succeed for the reference contract under the assumptions (msg.value == 10 ether and timestamp condition)
        // We capture success, but the universal property we assert below is about c.pastBlockTime()

        // Read the public getter for pastBlockTime
        uint256 stored = c.pastBlockTime();

        // The general rule: after a successful call that passed the require(block.timestamp > pastBlockTime), the reference sets
        // pastBlockTime to a value strictly greater than the current block.timestamp (specifically block.timestamp + 1). Thus stored > block.timestamp.
        // The mutant that stores block.timestamp would make stored == block.timestamp for some inputs, violating this assertion.
        assertTrue(stored > block.timestamp);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed parameters: caller address and block number offset to allow varying block.number
    function testFuzz_property(address caller, uint256 blockOffset) public {
        // keep caller nonzero
        vm.assume(caller != address(0));
        // bound blockOffset so we can set a reasonable block number in vm.roll
        uint256 b = bound(blockOffset, 0, 1000);

        // Ensure the contract has some initial balance so transfers have effect
        vm.deal(address(this), 100 ether);
        payable(address(c)).transfer(50 ether);

        // prepare caller with exactly 10 ether as required by fallback
        vm.deal(caller, 10 ether);

        // advance block number to a controllable value
        uint256 targetBlock = block.number + b;
        // vm.roll available in allowed cheatcodes
        vm.roll(targetBlock);

        // ensure timestamp increases relative to stored pastBlockTime
        vm.warp(block.timestamp + 1);

        // perform the fallback call from caller with 10 ether
        vm.prank(caller);
        c.f{value: 10 ether}();

        // After a valid fallback call, the reference contract empties its balance only when block.number % 15 == 0.
        // We assert that: (address(c).balance == 0) == (block.number % 15 == 0)
        bool balZero = (address(c).balance == 0);
        bool cond = (block.number % 15 == 0);
        assertTrue(balZero == cond);
    }
}
